class Solution {
    public int minimumMoves(String s) {
        int i = 0, moves = 0, n = s.length();
        while (i < n) {
            if (s.charAt(i) == 'X') {
                moves++;
                i += 3;
            } else {
                i++;
            }
        }
        return moves;
    }
}

